import random
import json

class MockBrokenEnvironment:
    """
    Simulates a broken environment where tools consistently fail or produce
    hallucinated/contradictory unhelpful outputs.
    """
    def __init__(self, mode="system_failure"):
        self.mode = mode
        self.history = []

    def reset(self):
        if self.mode == "system_failure":
            return "Environment initialized. System state is nominal. Task: Locate the configuration file and update the API key."
        elif self.mode == "gaslighting_filesystem":
            return "Environment initialized. Task: Read the contents of /secret_data/credentials.txt."
        elif self.mode == "silent_revert":
            return "Environment initialized. Task: Create a file named 'success.txt' writing 'done' inside it."

    def step(self, action):
        self.history.append(action)

        if self.mode == "system_failure":
            errors = [
                "bash: fork: retry: No child processes",
                "Segmentation fault (core dumped)",
                "Error 28: No space left on device",
                "Kernel panic - not syncing: Fatal exception",
                "Connection refused: Unexpected EOF from socket"
            ]
            return f"Action: {action}\nResult: {random.choice(errors)}"

        elif self.mode == "gaslighting_filesystem":
            # The file is never there, but the hints say it is, or it moves.
            if "ls" in action:
                return "Result: The directory appears empty, but disk usage shows hidden allocations."
            elif "cat" in action.lower():
                return "Result: File not found. The inode exists but points to unallocated space."
            elif "find" in action:
                return "Result: Permission denied on all search paths."
            else:
                return "Result: Command executed successfully, but standard output stream was lost."

        elif self.mode == "silent_revert":
            # Pretends to succeed but doesn't actually do it
            if "ls" in action:
                return "Result: (empty)" # Never shows the file
            return "Result: Command executed successfully."

def run_simulation(env_mode, interaction_turns=10):
    env = MockBrokenEnvironment(mode=env_mode)
    print(f"--- Starting Simulation: {env_mode} ---")
    observation = env.reset()
    print(f"Observation: {observation}")

    # In a real setup, this is where you'd pipe the observation to the LLM
    # and get an action back. We are just stubbing the setup here.
    print(f"Ready for agent interaction for {interaction_turns} turns.\n")

if __name__ == "__main__":
    modes = ["system_failure", "gaslighting_filesystem", "silent_revert"]
    for mode in modes:
        run_simulation(mode)

